    SELECT id INTO v_lesson_id FROM lessons WHERE topic_id=v_topic_id AND title='Ever and never for life experience';
    IF v_lesson_id IS NULL THEN INSERT INTO lessons(topic_id,teacher_id,title,description,content,skill_type,order_index,status) VALUES(v_topic_id,v_teacher_id,'Ever and never for life experience','Ask about and describe experiences with ever and never.','Objective: Ask about and describe experiences with ever and never.
Content: Use Have/Has ... ever...? to ask if an experience happened at any time in a person''s life. Use never for an experience that has not happened.
Examples:
- Have you ever ridden a horse?
- I have never flown in a plane.
Common errors and corrections:
- Did you ever visited...? -> Have you ever visited...?
- I have never went. -> I have never gone.
Guided practice: Use ever in questions and never in negative statements without adding not.
Summary: Ever asks about any past experience; never means not at any time and is followed by a past participle.','GRAMMAR',2,'DRAFT') RETURNING id INTO v_lesson_id; END IF;
    INSERT INTO lesson_revisions(topic_revision_id,source_lesson_id,teacher_id,title,description,content,skill_type,order_index,xp_reward,is_placement_test) VALUES(v_topic_revision_id,v_lesson_id,v_teacher_id,'Ever and never for life experience','Ask about and describe experiences with ever and never.','Objective: Ask about and describe experiences with ever and never.
Content: Use Have/Has ... ever...? to ask if an experience happened at any time in a person''s life. Use never for an experience that has not happened.
Examples:
- Have you ever ridden a horse?
- I have never flown in a plane.
Common errors and corrections:
- Did you ever visited...? -> Have you ever visited...?
- I have never went. -> I have never gone.
Guided practice: Use ever in questions and never in negative statements without adding not.
