    IF v_lesson_id IS NULL THEN INSERT INTO lessons(topic_id,teacher_id,title,description,content,skill_type,order_index,status) VALUES(v_topic_id,v_teacher_id,'Just, already, yet, and unfinished time','Use present perfect time words for recent actions and unfinished periods.','Objective: Use present perfect time words for recent actions and unfinished periods.
Content: Use just for a recent action, already for an earlier-than-expected action, and yet in questions and negatives. Use the present perfect with today, this week, and other unfinished periods.
Examples:
- She has just arrived.
- Have you finished yet?
- I have already eaten.
Common errors and corrections:
- I just have finished. -> I have just finished.
- Did you finish yet? -> Have you finished yet?
Guided practice: Place just and already between have/has and the participle; place yet at the end of questions and negatives.
Summary: Just, already, and yet describe a present result or an unfinished time period.','GRAMMAR',3,'DRAFT') RETURNING id INTO v_lesson_id; END IF;
