    SELECT id INTO v_lesson_id FROM lessons WHERE topic_id=v_topic_id AND title='Present perfect and past simple time contrasts';
    IF v_lesson_id IS NULL THEN INSERT INTO lessons(topic_id,teacher_id,title,description,content,skill_type,order_index,status) VALUES(v_topic_id,v_teacher_id,'Present perfect and past simple time contrasts','Choose between present perfect and past simple with clear time references.','Objective: Choose between present perfect and past simple with clear time references.
Content: Use present perfect for an unfinished period or a present result without a finished time. Use past simple with finished times such as yesterday, last year, or in 2020.
Examples:
- I have visited Hue this year.
- I visited Hue last year.
Common errors and corrections:
- I have seen him yesterday. -> I saw him yesterday.
- She went to Paris this year. -> She has been to Paris this year when the year is unfinished.
Guided practice: Circle the time expression. Finished past time selects past simple; unfinished time or a present result selects present perfect.
Summary: Finished time uses past simple; unfinished time and present experience use present perfect.','GRAMMAR',4,'DRAFT') RETURNING id INTO v_lesson_id; END IF;
